import Testing

@testable import Decimal128TextCodec

/// Render vectors for ``Decimal128TextCodec/dpd128ToString(_:)``.
///
/// Every expected pairing was taken from the shared `string_bid_dpd` corpus,
/// which is generated by the `decimal128-c` engine, so these are an independent
/// oracle rather than this codec grading itself. They are chosen to cover the
/// surfaces the DPD layout actually distinguishes: both combination-field cases,
/// the exponent extremes, and coefficients that exercise every declet.
@Suite
struct TestDpd128ToString {

    static let vectors: [(hex: String, expected: String)] = [
        // === Specials: identical bit patterns to BID, no coefficient to lay out
        ("[7800000000000000,0000000000000000]", "Infinity"),
        ("[F800000000000000,0000000000000000]", "-Infinity"),
        ("[7C00000000000000,0000000000000000]", "NaN"),
        ("[FC00000000000000,0000000000000000]", "-NaN"),
        ("[7E00000000000000,0000000000000000]", "sNaN"),

        // === Case A: leading digit 0..7, exponent MSBs in G0G1
        ("[2208000000000000,0000000000000000]", "0"),
        ("[A208000000000000,0000000000000000]", "-0"),
        ("[2208000000000000,0000000000000001]", "1"),
        ("[A208000000000000,0000000000000001]", "-1"),
        ("[2208000000000000,0000000000000009]", "9"),

        // === Case B: leading digit 8 or 9, exponent MSBs displaced into G2G3
        ("[2208800000000000,0000000000000008]", "8E+2"),
        ("[220B400000000000,0000000000000008]", "8E+13"),
        ("[6E080FF3FCFF3FCF,F3FCFF3FCFF3FCFF]", "9999999999999999999999999999999999"),

        // === Exponent extremes
        ("[47FFC00000000000,0000000000000000]", "1.000000000000000000000000000000000E+6144"),
        ("[47FFC033790A64F9,FE910BDA994B3322]", "1.003198280313997724281686314944622E+6144"),
        ("[0000000000000000,0000000000000000]", "0E-6176"),
        ("[8000000000000000,0000000000000000]", "-0E-6176"),
        ("[0000000000000000,0000000000000009]", "9E-6176"),
        ("[0001000000000000,0000000000000009]", "9E-6172"),

        // === Coefficients with runs of zero declets
        ("[2202C00000000000,0020000000000000]", "0.000008000000000000000"),
        ("[23DE400000000002,0000000000000000]", "2.0000000000000000000E+1900"),
    ]

    @Test("hand-chosen DPD render vectors")
    func renderVectors() {
        for v in Self.vectors {
            let bits = Hex.parseBracketed(v.hex)
            #expect(Decimal128TextCodec.dpd128ToString(bits) == v.expected, "for \(v.hex)")
        }
    }

    /// The two formats must agree on every value: same text from peer encodings.
    @Test("peer BID and DPD encodings render identically")
    func dpdAndBidAgree() {
        let pairs = [
            ("[3040000000000000,0000000000000001]", "[2208000000000000,0000000000000001]"), // 1
            ("[3040000000000000,0000000000000009]", "[2208000000000000,0000000000000009]"), // 9
            ("[7800000000000000,0000000000000000]", "[7800000000000000,0000000000000000]"), // Infinity
            ("[3041ED09BEAD87C0,378D8E63FFFFFFFF]", "[6E080FF3FCFF3FCF,F3FCFF3FCFF3FCFF]"), // 34 nines
        ]
        for (bidHex, dpdHex) in pairs {
            #expect(Decimal128TextCodec.bid128ToString(Hex.parseBracketed(bidHex))
                    == Decimal128TextCodec.dpd128ToString(Hex.parseBracketed(dpdHex)),
                    "peer encodings disagree: \(bidHex) vs \(dpdHex)")
        }
    }
}

/// Parse vectors for ``Decimal128TextCodec/dpd128Parse(_:_:)``, and the NaN
/// payload cases that separate the two formats.
///
/// A NaN payload is a coefficient, so it is declet-encoded in DPD exactly as a
/// finite coefficient is. Payloads below 10 happen to coincide with BID; from
/// two digits up they diverge. Every expected pairing comes from the shared
/// `string_bid_dpd` corpus.
@Suite
struct TestDpd128Parse {

    static let vectors: [(expectedHex: String, str: String)] = [
        // === Finite: the same grammar and rounding as BID, a different encoding
        ("[2208000000000000,0000000000000000]", "0"),
        ("[A208000000000000,0000000000000000]", "-0"),
        ("[2208000000000000,0000000000000001]", "1"),
        ("[A208000000000000,0000000000000001]", "-1"),
        ("[2208000000000000,0000000000000009]", "9"),
        ("[6E080FF3FCFF3FCF,F3FCFF3FCFF3FCFF]", "9999999999999999999999999999999999"),
        ("[0000000000000000,0000000000000009]", "9E-6176"),

        // === Infinity: no coefficient, so byte-identical to BID
        ("[7800000000000000,0000000000000000]", "Infinity"),
        ("[F800000000000000,0000000000000000]", "-Infinity"),

        // === NaN payloads: coincide with BID below 10, diverge from two digits up
        ("[7C00000000000000,0000000000000000]", "NaN"),
        ("[7C00000000000000,0000000000000001]", "NaN1"),
        ("[7C00000000000000,0000000000000010]", "NaN10"),
        ("[7C00000000000000,0000000000000081]", "NaN101"),
        ("[FE00000000000000,00000000534B9C1E]", "-sNaN1234567890"),
        ("[7C00000000000000,0BDA60F498388E4E]", "NaN576460752303423488"),
        ("[7C00000000000000,1000000000000000]", "NaN1000000000000000000"),
        ("[7C000928CF8BFD99,413B2DCB4DF63344]", "NaN112433781776314088827827199902644"),
        ("[7E000000000152A2,BCADC0B0E5E29592]", "sNaN1284483683340543498125312"),
        ("[FE00000340C8971F,13CBA29DF88620BE]", "-sNaN150148854371172722477708308918"),
        ("[FC0000000001422A,D0FF14CA4F4E18F6]", "-NaN1208925819614629174706176"),
    ]

    @Test("hand-chosen DPD parse vectors")
    func parseVectors() {
        for v in Self.vectors {
            let d = dpdParse(v.str)
            #expect(d.error == nil, "unexpected error for \(v.str): \(d.error ?? "")")
            #expect(d.bits == Hex.parseBracketed(v.expectedHex), "for \(v.str)")
        }
    }

    /// Every vector must round-trip: parse then render returns the input.
    @Test("DPD parse then render returns the input")
    func roundTrip() {
        for v in Self.vectors {
            let d = dpdParse(v.str)
            #expect(d.error == nil)
            #expect(Decimal128TextCodec.dpd128ToString(d.bits) == v.str)
        }
    }

    /// Failures behave as they do for BID, and yield the canonical quiet NaN.
    @Test("DPD rejects exactly what BID rejects")
    func failuresMatchBid() {
        for bad in ["", "abc", "1.2.3", "1E", "1E+", "1_", "_1", "NaNx", "."] {
            let d = dpdParse(bad)
            let b = bidParse(bad)
            #expect(d.error != nil, "expected failure for <\(bad)>")
            #expect(b.error == d.error, "the formats must reject <\(bad)> the same way")
            #expect(d.bits == canonicalQuietNaN)
        }
    }
}

/// Exhaustive tests for the DPD declet primitives.
///
/// A declet is 10 bits, so the entire input domain is 1024 values for decode and
/// 1000 for encode. These enumerate both completely: no sampling, and no oracle
/// needed beyond the format's own definition.
@Suite
struct TestDpdDeclet {

    @Test("every declet decodes into 0...999")
    func everyDecletDecodesInRange() {
        for declet in UInt64(0)...1023 {
            let v = Decimal128TextCodec.dpdDecodeDeclet(declet)
            #expect(v <= 999, "declet \(declet) decoded to \(v), out of 0...999")
        }
    }

    @Test("every value encodes into ten bits")
    func everyValueEncodesToTenBits() {
        for n in UInt64(0)...999 {
            let d = Decimal128TextCodec.dpdEncodeDeclet(n)
            #expect(d <= 1023, "value \(n) encoded to \(d), wider than 10 bits")
        }
    }

    /// encode is a right inverse of decode over the whole value domain.
    @Test("decode(encode(n)) == n")
    func encodeThenDecodeIsIdentity() {
        for n in UInt64(0)...999 {
            #expect(Decimal128TextCodec.dpdDecodeDeclet(Decimal128TextCodec.dpdEncodeDeclet(n)) == n)
        }
    }

    /// Every value 0..999 is reachable, and exactly 1000 of the 1024 declets are
    /// canonical. The other 24 are the non-canonical encodings: they decode to a
    /// legal value, but re-encoding yields the canonical declet instead.
    @Test("1000 canonical declets, 24 non-canonical, every value reachable")
    func canonicalAndNonCanonicalDecletsAreAccountedFor() {
        var seen = Set<UInt64>()
        var canonical = 0
        var nonCanonical = 0
        for declet in UInt64(0)...1023 {
            let v = Decimal128TextCodec.dpdDecodeDeclet(declet)
            seen.insert(v)
            if Decimal128TextCodec.dpdEncodeDeclet(v) == declet {
                canonical += 1
            } else {
                nonCanonical += 1
            }
        }
        #expect(seen.count == 1000, "not every value in 0...999 is reachable")
        #expect(canonical == 1000)
        #expect(nonCanonical == 24)
    }

    /// Zero must round-trip as the all-zero declet, not merely as some encoding
    /// of 0.
    @Test("zero is the all-zero declet")
    func zeroIsTheAllZeroDeclet() {
        #expect(Decimal128TextCodec.dpdEncodeDeclet(0) == 0)
        #expect(Decimal128TextCodec.dpdDecodeDeclet(0) == 0)
    }

    /// Regression pins on specific encodings.
    ///
    /// `9` and `999` were derived by hand from Cowlishaw's bcd2dpd equations to
    /// confirm the rest: for 999 all three digits are 1001, giving
    /// `pqrstuvwxy = 0011111111` = 0x0FF; for 9 only `v` and `y` are set, giving
    /// 0x009. The remainder are here to catch drift, not to independently prove
    /// the equations — the exhaustive properties above do that.
    @Test("known declet encodings")
    func knownDecletEncodings() {
        #expect(Decimal128TextCodec.dpdEncodeDeclet(9) == 0x009)     // hand-derived
        #expect(Decimal128TextCodec.dpdEncodeDeclet(999) == 0x0FF)   // hand-derived
        #expect(Decimal128TextCodec.dpdEncodeDeclet(5) == 0x005)
        #expect(Decimal128TextCodec.dpdEncodeDeclet(8) == 0x008)
        #expect(Decimal128TextCodec.dpdEncodeDeclet(57) == 0x057)
        #expect(Decimal128TextCodec.dpdEncodeDeclet(98) == 0x05E)
        #expect(Decimal128TextCodec.dpdEncodeDeclet(198) == 0x0DE)
        #expect(Decimal128TextCodec.dpdEncodeDeclet(321) == 0x1A1)
        #expect(Decimal128TextCodec.dpdEncodeDeclet(399) == 0x1DF)
    }
}

/// Non-canonical DPD128 encodings.
///
/// DPD's non-canonicality is narrower than BID's, and structurally so:
///
///  - The combination field cannot encode an out-of-range exponent. In both
///    cases the exponent's top two bits come from a field restricted to `00`,
///    `01` or `10`, so the biased exponent cannot exceed 12287, which is exactly
///    the format maximum of qExp 6111.
///  - The coefficient cannot exceed 10^34 - 1: a leading digit of at most 9
///    followed by eleven declets of at most 999 reaches exactly that bound.
///
/// So unlike BID there is no coefficient-too-large rule to apply. What remains
/// is the 24 non-canonical declets — the "don't care" patterns, all decoding to
/// values whose last two digits are both 8 or 9 — and junk bits in the trailing
/// field of an infinity.
@Suite
struct TestDpd128NonCanonical {

    /// The 24 declet patterns that are not produced by canonical encoding.
    static let nonCanonicalDeclets: [UInt64] = [
        0x16E, 0x16F, 0x17E, 0x17F, 0x1EE, 0x1EF, 0x1FE, 0x1FF,
        0x26E, 0x26F, 0x27E, 0x27F, 0x2EE, 0x2EF, 0x2FE, 0x2FF,
        0x36E, 0x36F, 0x37E, 0x37F, 0x3EE, 0x3EF, 0x3FE, 0x3FF,
    ]

    /// qExp 0, leading digit 0, positive.
    static let base: UInt64 = 0x2208_0000_0000_0000

    @Test("the twenty-four are truly non-canonical")
    func theTwentyFourAreTrulyNonCanonical() {
        for d in Self.nonCanonicalDeclets {
            let v = Decimal128TextCodec.dpdDecodeDeclet(d)
            #expect(Decimal128TextCodec.dpdEncodeDeclet(v) != d,
                    "0x\(String(d, radix: 16)) should not be the canonical form of \(v)")
            #expect(v % 10 >= 8 && (v / 10) % 10 >= 8,
                    "every non-canonical declet decodes to a value ending in two digits >= 8; \(v) does not")
        }
    }

    /// A non-canonical declet renders exactly as its canonical spelling does.
    @Test("non-canonical declets render as canonical")
    func nonCanonicalRendersAsCanonical() {
        for d in Self.nonCanonicalDeclets {
            let canon = Decimal128TextCodec.dpdEncodeDeclet(Decimal128TextCodec.dpdDecodeDeclet(d))
            // low group, declet 0
            #expect(Decimal128TextCodec.dpd128ToString(words(Self.base, canon))
                    == Decimal128TextCodec.dpd128ToString(words(Self.base, d)),
                    "low-group declet 0x\(String(d, radix: 16))")
            // high group, declet 1 -- T begins at bit 4 of the high group, so
            // declet i starts at the high word's bit (i*10 - 4)
            #expect(Decimal128TextCodec.dpd128ToString(words(Self.base | (canon << 6), 0))
                    == Decimal128TextCodec.dpd128ToString(words(Self.base | (d << 6), 0)),
                    "high-group declet 0x\(String(d, radix: 16))")
        }
    }

    /// Re-parsing a non-canonical encoding yields the canonical one.
    @Test("re-parsing normalises")
    func reparsingNormalises() {
        for d in Self.nonCanonicalDeclets {
            let canon = Decimal128TextCodec.dpdEncodeDeclet(Decimal128TextCodec.dpdDecodeDeclet(d))
            let text = Decimal128TextCodec.dpd128ToString(words(Self.base, d))
            let out = dpdParse(text)
            #expect(out.error == nil)
            #expect(out.bits == words(Self.base, canon),
                    "0x\(String(d, radix: 16)) should re-encode as 0x\(String(canon, radix: 16))")
        }
    }

    /// Canonical output never emits a non-canonical declet.
    @Test("encoding never produces a non-canonical declet")
    func encodingNeverProducesNonCanonicalDeclets() {
        let nc = Set(Self.nonCanonicalDeclets)
        for text in [
            "0", "1", "9", "88", "99", "888", "899", "988", "999",
            "9999999999999999999999999999999999",
            "8888888888888888888888888888888888",
            "9898989898989898989898989898989898",
            "1.888888888888888888888888888888888E+99",
            "NaN999", "NaN888999888999888999888999888999",
            "-sNaN999999999999999999999999999999999",
        ] {
            let out = dpdParse(text)
            #expect(out.error == nil, "parse failed for \(text)")
            for d in Self.declets(of: out.bits) {
                #expect(!nc.contains(d),
                        "encoding of \(text) emitted non-canonical declet 0x\(String(d, radix: 16))")
            }
        }
    }

    /// Infinity ignores whatever sits in the trailing field.
    @Test("infinity ignores trailing bits")
    func infinityIgnoresTrailingBits() {
        for lo: UInt64 in [0, 1, 0x3FF, UInt64.max, 0x1FF] {
            #expect(Decimal128TextCodec.dpd128ToString(words(0x7800_0000_0000_0000, lo)) == "Infinity")
            #expect(Decimal128TextCodec.dpd128ToString(words(0xF800_0000_0000_0000, lo)) == "-Infinity")
        }
        // and junk in the high group too
        #expect(Decimal128TextCodec.dpd128ToString(words(0x7800_FFFF_FFFF_FFFF, UInt64.max)) == "Infinity")
    }

    /// A NaN payload is a coefficient, so its declets normalise the same way.
    @Test("NaN payload declets normalise")
    func nanPayloadDecletsNormalise() {
        for d in Self.nonCanonicalDeclets {
            let canon = Decimal128TextCodec.dpdEncodeDeclet(Decimal128TextCodec.dpdDecodeDeclet(d))
            #expect(Decimal128TextCodec.dpd128ToString(words(0x7C00_0000_0000_0000, canon))
                    == Decimal128TextCodec.dpd128ToString(words(0x7C00_0000_0000_0000, d)),
                    "NaN payload declet 0x\(String(d, radix: 16))")
        }
    }

    /// All eleven declets of the trailing significand field.
    static func declets(of bits: UInt128) -> [UInt64] {
        let hi = hiWord(bits)
        let lo = loWord(bits)
        var out = [UInt64](repeating: 0, count: 11)
        for i in 0..<6 {
            out[i] = (lo >> UInt64(i * 10)) & 0x3FF
        }
        let high = ((hi & 0x3FFF_FFFF_FFFF) << 4) | (lo >> 60)
        for i in 0..<5 {
            out[6 + i] = (high >> UInt64(i * 10)) & 0x3FF
        }
        return out
    }
}
